const body = $input.first().json.body || $input.first().json;

const itemId = body.item_id;
const itemName = body.item_name || 'Unknown Item';
const currentStock = body.current_stock;
const minimumStock = body.minimum_stock;
const supplierId = body.supplier_id;
const projectId = body.project_id || 'N/A';
const unit = body.unit || 'units';
const warehouseLocation = body.warehouse_location || 'Main Warehouse';

const now = new Date();
const formattedDate = now.toLocaleDateString('pt-BR', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

const telegramMessage = [
  `\u26a0\ufe0f *ALERTA DE ESTOQUE BAIXO*`,
  ``,
  `\ud83d\udce6 *Item:* ${itemName}`,
  `\ud83c\udff7\ufe0f *ID:* \`${itemId}\``,
  `\ud83d\udccd *Local:* ${warehouseLocation}`,
  ``,
  `\ud83d\udcca *Estoque Atual:* ${currentStock} ${unit}`,
  `\ud83d\udd34 *Estoque Mínimo:* ${minimumStock} ${unit}`,
  `\ud83d\udcc9 *Abaixo do mínimo por:* ${minimumStock - currentStock} ${unit}`,
  ``,
  `\ud83d\udd17 *Fornecedor ID:* ${supplierId}`,
  `\ud83d\uddd3\ufe0f *Data/Hora:* ${formattedDate}`,
  ``,
  `_Pedido de reposição enviado automaticamente ao fornecedor._`
].join('\n');

const suggestedOrderQuantity = Math.max(minimumStock * 3 - currentStock, minimumStock * 2);

return [{
  json: {
    item_id: itemId,
    item_name: itemName,
    current_stock: currentStock,
    minimum_stock: minimumStock,
    supplier_id: supplierId,
    project_id: projectId,
    unit: unit,
    warehouse_location: warehouseLocation,
    formatted_date: formattedDate,
    telegram_message: telegramMessage,
    suggested_order_quantity: suggestedOrderQuantity
  }
}];
